-- SP_Activate_DeActivate_Quotation
CREATE PROCEDURE DBO.SP_Activate_DeActivate_Quotation
	@List VARCHAR(8000),
	@NewValue CHAR(1),
	@OldValue CHAR(1)
AS
/*
Author :
	M. Azhar Inayat
Purpose:
	To Activate/DeActivate a range of quotations

PARAMETER DESCRIPTION :
	@List = A comma separated list of quotation codes to be processed
	@NewValue = Y OR N activate Y/N
	@OldValue = Y OR N activate Y/N
*/

DELETE ReportData

DECLARE @Tab_List TABLE (CODE INT NOT NULL)

INSERT INTO @Tab_List SELECT CODE FROM udf_StringToTabl(@List, ',')

UPDATE QuotationHeader 
SET Active = @NewValue
WHERE Active = @OldValue AND QuotationCode IN (SELECT Code FROM @Tab_List) 

RETURN 0

-- sp_GetCustWiseLatestItemSale
CREATE  Procedure sp_GetCustWiseLatestItemSale 
	@custcode Int, 
	@icode Int, 
	@saleprice Numeric(8,2) OUTPUT,  
	@looseqty NUMERIC(15, 4) OUTPUT, 
	@bonusqty NUMERIC(15, 4) OUTPUT, 
	@discperc Numeric(5,2) OUTPUT, 
	@itemflatdisc Numeric(12,2) OUTPUT, 
	@rows SmallInt OUTPUT As

Select @rows = count(*) , @saleprice = Max(saledetail.saleprice) , @looseqty = Sum(saledetail.looseqty) , @bonusqty = Sum(saledetail.bonusqty) , @discperc = Max(saledetail.discperc) , @itemflatdisc = Max(saledetail.itemflatdisc)
From saleledger , saledetail , 
(
Select date = max(sl.date) 
from saleledger sl, saledetail sd
where sl.custcode = @custcode And
      sl.saleinvcode = sd.saleinvcode And
      sd.icode = @icode
) A

Where   saleledger.custcode = @custcode And 
	saleledger.date = A.date And 
	saleledger.saleinvcode = saledetail.saleinvcode And
	saledetail.icode = @icode

Group By saledetail.icode,
	 saledetail.saleprice,
	 saledetail.discperc,
	 saledetail.itemflatdisc

