	@ICatCode SMALLINT OUT, 
	@PackCode SMALLINT OUT, 
	@OCLimit INT OUT, 
	@MCLimit INT OUT, 
	@SCLimit INT OUT
AS

SET NOCOUNT ON

SELECT 
	@ICatCode = ISNULL(PCC.ICatCode,0), 
	@PackCode = ISNULL(PCC.PackCode,0), 
	@OCLimit = ISNULL(PCC.OCQty,0), 
	@MCLimit = ISNULL(PCC.MCQty,0), 
	@SCLimit = ISNULL(PCC.SCQty,0)
FROM 
	PackingCaseCapacity PCC, Item I
WHERE 
	I.ICode = @ICode AND
	I.ICatCode = PCC.ICatCode AND
