-- SP_GetPatientAge
CREATE PROCEDURE DBO.SP_GetPatientAge 
	@PatientCode INT,
	@AgeYears INT OUTPUT,
	@AgeMonth INT OUTPUT,
	@AgeDays  INT OUTPUT
AS

Set NoCount ON

SELECT 
	@AgeYears = DATEDIFF(yy, P.DOB, getdate()),
	@AgeMonth = CAST(DATEDIFF(dd, P.DOB, getdate()) % 360 / 30 AS INT),
	@AgeDays = CAST(DATEDIFF(dd, P.DOB, getdate()) % 360 % 30 AS INT)
FROM
	Patient P
WHERE
	P.PatientCode = @PatientCode

SET @AgeYears = ISNULL(@AgeYears, 0)
SET @AgeMonth = ISNULL(@AgeMonth, 0)
SET @AgeDays = ISNULL(@AgeDays, 0)

Set NoCount OFF
RETURN 0

-- SP_GetPatientInfo
CREATE PROCEDURE DBO.SP_GetPatientInfo
	@PatientCode INT,
	@RegNo VARCHAR(100) OUTPUT,
	@PatientName VARCHAR(100) OUTPUT,
	@FName VARCHAR(100) OUTPUT,	
	@DOB DATETIME OUTPUT,
	@Gender CHAR(1) OUTPUT,
	@CustCode INT OUTPUT,
	@Address1 VARCHAR(100) OUTPUT,	
	@Address2 VARCHAR(100) OUTPUT,	
	@Phone VARCHAR(100) OUTPUT,	
	@AgeYears INT OUTPUT,
	@AgeMonths INT OUTPUT,
	@AgeDays INT OUTPUT
AS

SELECT 
	@RegNo = P.RegNo,
	@PatientName = P.Name,
	@FName = P.FName,	
	@DOB = P.DOB,
	@Gender = P.Gender,
	@CustCode = P.CustCode,
	@Address1 = P.Address1,	
	@Address2 = P.Address2,
	@Phone = P.Phone
FROM
	Patient P
WHERE 
	P.PatientCode = @PatientCode

IF @PatientName IS NOT NULL
BEGIN
	EXECUTE DBO.SP_GetPatientAge @PatientCode, @AgeYears OUT, @AgeMonths OUT, @AgeDays OUT
END

RETURN 0

-- SP_GetServiceInfo
CREATE PROCEDURE DBO.SP_GetServiceInfo
	@ServiceInvCode INT,
	@ServiceDate DATETIME OUTPUT,
	@PatientCode INT OUTPUT,
	@RegNo VARCHAR(100) OUTPUT,
	@PatientName VARCHAR(100) OUTPUT,
	@FName VARCHAR(100) OUTPUT,
	@DOB DATETIME OUTPUT,
	@Gender CHAR(1) OUTPUT,
	@CustCode INT OUTPUT,
	@Address1 VARCHAR(100) OUTPUT,	
	@Address2 VARCHAR(100) OUTPUT,	
	@Phone VARCHAR(100) OUTPUT,	
	@AgeYears INT OUTPUT,
	@AgeMonths INT OUTPUT,
	@AgeDays INT OUTPUT,
	@AdmissionCode INT OUTPUT,
	@PatientLocation INT OUTPUT
AS

Set NoCount ON

SELECT 
	@ServiceDate=SH.Date,
	@PatientCode = 	
		(SELECT P.PatientCode FROM Patient P
		WHERE P.PatientCode IN 
			(SELECT PatientCode=SH.PatientCode 
			UNION ALL
			SELECT PA.PatientCode 
			FROM PatientAdmission PA
			WHERE PA.AdmissionCode = SH.AdmissionCode)),
	@AdmissionCode = SH.AdmissionCode
FROM
	ServiceHeader SH
WHERE
	SH.ServiceInvCode = @ServiceInvCode

IF @ServiceInvCode > 0
BEGIN
	IF @PatientCode > 0
	BEGIN
		EXECUTE DBO.SP_GetPatientInfo @PatientCode, @RegNo OUT, @PatientName OUT, @FName OUT, @DOB OUT, @Gender OUT, @CustCode OUT, @Address1 OUT, @Address2 OUT, @Phone OUT, @AgeYears OUT, @AgeMonths OUT, @AgeDays OUT
	END

	IF @AdmissionCode > 0
	BEGIN
		SELECT 
			@PatientLocation = PA.LocationCode
		FROM
			PatientAdmission PA
		WHERE 
			PA.AdmissionCode = @AdmissionCode

	END
END

RETURN 0

-- SP_GetServiceRowInfo
CREATE PROCEDURE DBO.SP_GetServiceRowInfo
	@ServiceRowID INT,
	@ServiceInvCode INT OUTPUT,
	@ServiceDate DATETIME OUTPUT,
	@PatientCode INT OUTPUT,
	@RegNo VARCHAR(100) OUTPUT,
	@PatientName VARCHAR(100) OUTPUT,
	@FName VARCHAR(100) OUTPUT,
	@DOB DATETIME OUTPUT,
	@Gender CHAR(1) OUTPUT,
	@CustCode INT OUTPUT,
	@Address1 VARCHAR(100) OUTPUT,	
	@Address2 VARCHAR(100) OUTPUT,	
	@Phone VARCHAR(100) OUTPUT,	
	@AgeYears INT OUTPUT,
	@AgeMonths INT OUTPUT,
	@AgeDays INT OUTPUT,
	@AdmissionCode INT OUTPUT,
	@PatientLocation INT OUTPUT,
	@ServiceCode INT OUTPUT,
	@DeliveryDate DATETIME OUTPUT
AS

Set NoCount ON

SELECT 
	@ServiceInvCode=SD.ServiceInvCode,
	@ServiceDate=SH.Date,
	@PatientCode = 	
		(SELECT P.PatientCode FROM Patient P
		WHERE P.PatientCode IN 
			(SELECT PatientCode=SH.PatientCode 
			UNION ALL
			SELECT PA.PatientCode 
			FROM PatientAdmission PA
			WHERE PA.AdmissionCode = SH.AdmissionCode)),
	@AdmissionCode = SH.AdmissionCode,
	@ServiceCode=SD.ServiceCode,
	@DeliveryDate=SD.DeliveryDate
FROM
	ServiceDetail SD, ServiceHeader SH
WHERE
	SD.SrvRowID = @ServiceRowID AND
	SD.ServiceInvCode = SH.ServiceInvCode

IF @ServiceInvCode > 0 AND @ServiceCode > 0
BEGIN
	IF @PatientCode > 0
	BEGIN
		EXECUTE DBO.SP_GetPatientInfo @PatientCode, @RegNo OUT, @PatientName OUT, @FName OUT, @DOB OUT, @Gender OUT, @CustCode OUT, @Address1 OUT, @Address2 OUT, @Phone OUT, @AgeYears OUT, @AgeMonths OUT, @AgeDays OUT
	END

	IF @AdmissionCode > 0
	BEGIN
		SELECT 
			@PatientLocation = PA.LocationCode
		FROM
			PatientAdmission PA
		WHERE 
			PA.AdmissionCode = @AdmissionCode

	END
END

RETURN 0

-- SP_GetVersionInfo
CREATE   PROCEDURE SP_GetVersionInfo
	@SRV VARCHAR(50), 
	@DB VARCHAR(50), 
	@OWNER VARCHAR(20),
	@SequenceID INT OUTPUT,
	@AppVersion INT OUTPUT,
	@DBStatus INT OUTPUT
AS

SET ANSI_NULLS ON
SET ANSI_WARNINGS ON

DELETE REPORTDATA
DECLARE @qry VARCHAR(1000) 
SET @qry = 'INSERT INTO REPORTDATA (code1, code2, code3) SELECT * FROM ' + @SRV + '.' + @DB + '.' + @OWNER + '.Sequence'
EXECUTE (@qry)
SET @SequenceID = (SELECT Code1 FROM REPORTDATA)
SET @AppVersion = (SELECT Code2 FROM REPORTDATA)
SET @DBStatus = (SELECT Code3 FROM REPORTDATA)

