-- SP_Update_Customer_Info
CREATE PROCEDURE DBO.SP_Update_Customer_Info
@ai_custcode SMALLINT,
@ai_areacode SMALLINT,
@ai_subareacode SMALLINT,
@ai_countycode SMALLINT,
@as_address1 VARCHAR(60),
@as_address2 VARCHAR(60),
@as_block CHAR(1),
@ad_charges NUMERIC(12,2),
@adt_openingdate DATETIME
AS

UPDATE Accounts SET OpeningDate=@adt_openingdate WHERE AccCOde=@ai_custcode

UPDATE Customer 
SET 
	Address1 = @as_address1,
	Address2 = @as_address2,
	AreaCode = @ai_areacode,
	SubAreaCode = @ai_subareacode,
	CountyCode = @ai_countycode,
	Block = @as_block,
	Charges = @ad_charges
WHERE CustCOde=@ai_custcode
